#include <Arduino.h>
#include <RF24.h>
#include <SPI.h>
#include <esp_bt.h>
#include <esp_wifi.h>
#include <esp_bt_main.h>

// Yangi qo'shilgan kutubxonalar
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <MFRC522.h>

// OLED Ekran sozlamalari
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

// RC522 RFID sozlamalari
#define RST_PIN         26
#define SS_PIN          25
MFRC522 mfrc522(SS_PIN, RST_PIN);
MFRC522::MIFARE_Key key;

// Rejim tugmasi va holatlari
#define BUTTON_PIN      34
enum DeviceMode { MODE_JAMMER, MODE_RFID_MENU, MODE_RFID_READ, MODE_RFID_WRITE };
DeviceMode currentMode = MODE_JAMMER;
unsigned long lastDebounceTime = 0;
unsigned long debounceDelay = 250; // Tugma bosilishini aniqlash vaqti

// RFID ma'lumotlarini vaqtincha saqlash uchun bufer (Duplikator uchun)
byte storedUID[4];
bool hasStoredCard = false;

// Mavjud NRF24 o'zgaruvchilari (O'zgartirilmadi)
SPIClass *sp = nullptr;
RF24 radioA(5, 17, 19909090);
RF24 radioB(16, 4, 19909090);

int HSPIchannel = 45;
int VSPIchannel = 45;
unsigned int HSPIflag = 0;
unsigned int VSPIflag = 0;

// Mavjud funksiyalar (O'zgartirilmadi)
void channelSweeper() {
  if (VSPIflag == 0) VSPIchannel += 4; else VSPIchannel -= 4;
  if (HSPIflag == 0) HSPIchannel += 2; else HSPIchannel -= 2;
  if ((VSPIchannel > 79) && (VSPIflag == 0)) VSPIflag = 1; else if ((VSPIchannel < 2) && (VSPIflag == 1)) VSPIflag = 0;
  if ((HSPIchannel > 79) && (HSPIflag == 0)) HSPIflag = 1; else if ((HSPIchannel < 2) && (HSPIflag == 1)) HSPIflag = 0;
  radioA.setChannel(HSPIchannel);
  radioB.setChannel(VSPIchannel);
}

void randomChannel() {
  radioA.setChannel(random(80));
  radioB.setChannel(random(80));
  delayMicroseconds(random(60));
}

void initHSPI() {
  sp = new SPIClass(VSPI);
  sp->begin(18, 19, 23);
  if (radioA.begin(sp)) {
    radioA.setAutoAck(false);
    radioA.stopListening();
    radioA.setRetries(0, 0);
    radioA.setPayloadSize(32);
    radioA.setAddressWidth(5);
    radioA.setPALevel(RF24_PA_MAX, true);
    radioA.setDataRate(RF24_2MBPS);
    radioA.setCRCLength(RF24_CRC_DISABLED);
    radioA.startConstCarrier(RF24_PA_MAX, HSPIchannel);
  }
}

void initVSPI() {
  if (radioB.begin(sp)) {
    radioB.setAutoAck(false);
    radioB.stopListening();
    radioB.setRetries(0, 0);
    radioB.setPayloadSize(32);
    radioB.setAddressWidth(5);
    radioB.setPALevel(RF24_PA_MAX, true);
    radioB.setDataRate(RF24_2MBPS);
    radioB.setCRCLength(RF24_CRC_DISABLED);
    radioB.startConstCarrier(RF24_PA_MAX, VSPIchannel);
  }
}

// Yangi ekran yangilash funksiyasi
void updateDisplay() {
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);

  display.println("=== MULTI-TOOL OS ===");
  display.println();

  if (currentMode == MODE_JAMMER) {
    display.setTextSize(2);
    display.println("JAMMER: ON");
    display.setTextSize(1);
    display.println("Freq: 2.4 GHz Sweep");
  } 
  else if (currentMode == MODE_RFID_MENU) {
    display.println("> RFID Duplicator");
    display.println("  [Press to Enter]");
  }
  else if (currentMode == MODE_RFID_READ) {
    display.println("Mode: RFID READ");
    display.println("Karta yaqinlashtiring...");
    if (hasStoredCard) {
      display.print("Saqlangan UID: ");
      for (byte i = 0; i < 4; i++) {
        display.print(storedUID[i], HEX);
        display.print(" ");
      }
    }
  }
  else if (currentMode == MODE_RFID_WRITE) {
    display.println("Mode: RFID WRITE");
    if (hasStoredCard) {
      display.println("Yoziladigan UID yuklangan.");
      display.println("Yangi kartani qo'ying...");
    } else {
      display.println("Xatolik: Avval kartani");
      display.println("o'qib oling!");
    }
  }

  display.display();
}

// Tugma bosilishini tekshirish (Rejimlarni boshqarish)
void checkButton() {
  int btnState = digitalRead(BUTTON_PIN);
  if (btnState == LOW) { // Tugma bosilganda (Pull-up ulangan deb hisoblasak)
    if ((millis() - lastDebounceTime) > debounceDelay) {
      // Rejimlarni aylanma almashtirish
      if (currentMode == MODE_JAMMER) currentMode = MODE_RFID_MENU;
      else if (currentMode == MODE_RFID_MENU) currentMode = MODE_RFID_READ;
      else if (currentMode == MODE_RFID_READ) currentMode = MODE_RFID_WRITE;
      else if (currentMode == MODE_RFID_WRITE) currentMode = MODE_JAMMER;

      updateDisplay();
      lastDebounceTime = millis();
    }
  }
}

// RFID Kartani o'qish funksiyasi
void handleRFIDRead() {
  if (!mfrc522.PICC_IsNewCardPresent() || !mfrc522.PICC_ReadCardSerial()) {
    return;
  }

  // UID ni xotiraga saqlab olish
  for (byte i = 0; i < 4; i++) {
    storedUID[i] = mfrc522.uid.uidByte[i];
  }
  hasStoredCard = true;

  display.clearDisplay();
  display.setCursor(0, 0);
  display.println("Karta muvaffaqiyatli");
  display.println("o'qildi va saqlandi!");
  display.display();
  delay(1500);

  currentMode = MODE_RFID_MENU; // O'qib bo'lingach menyuga qaytadi
  updateDisplay();
}

// RFID Kartaga yozish (Duplikat qilish) funksiyasi
void handleRFIDWrite() {
  if (!hasStoredCard) return;

  if (!mfrc522.PICC_IsNewCardPresent() || !mfrc522.PICC_ReadCardSerial()) {
    return;
  }

  // Mifare klassik kartalarining 0-blokiga (UID bloki) yozishga urinish
  // Eslatma: UID o'zgartirsa bo'ladigan maxsus (UID Changeable) Xitoy kartalari kerak bo'ladi
  byte sector = 0;
  byte blockAddr = 0;
  byte trailerBlock = 3;
  MFRC522::StatusCode status;

  // Standart kalit zavod sozlamasi bo'yicha (0xFF FFFF FFFF FFFF)
  for (byte i = 0; i < 6; i++) key.keyByte[i] = 0xFF;

  // Autentifikatsiya
  status = mfrc522.PCD_Authenticate(MFRC522::PICC_CMD_MF_AUTH_KEY_A, trailerBlock, &key, &(mfrc522.uid));
  if (status != MFRC522::STATUS_OK) {
     display.clearDisplay();
     display.println("Auth Xatolik!");
     display.display();
     delay(1000);
     return;
  }

  // Yangi UID ma'lumotlar blokini tayyorlash (faqat 4 bayt UID yoziladi, qolgan qismi eski blokdan olinadi)
  byte buffer[16];
  byte size = sizeof(buffer);

  // Avval blok 0 dagi ma'lumotni o'qib olamiz (ishlab chiqaruvchi ma'lumotlarini buzmaslik uchun)
  status = mfrc522.MIFARE_Read(blockAddr, buffer, &size);

  // Yangi UID ni bufer boshiga joylashtiramiz
  for(int i=0; i<4; i++) {
    buffer[i] = storedUID[i];
  }
  // Qolgan baytlar (BCC check va h.k) avtomatik hisoblanishi kerak, oddiy nusxalashda:
  buffer[4] = buffer[0] ^ buffer[1] ^ buffer[2] ^ buffer[3]; // BCC hisoblash

  // Blok 0 ga yangi ma'lumotni yozish
  status = mfrc522.MIFARE_Write(blockAddr, buffer, 16);
  if (status == MFRC522::STATUS_OK) {
    display.clearDisplay();
    display.println("Klonlash muvaffaqiyatli!");
    display.display();
    delay(2000);
    currentMode = MODE_JAMMER; // Ish yakunlangach Jammerga qaytadi
  } else {
    display.clearDisplay();
    display.println("Yozishda xatolik!");
    display.println("Karta mos kelmadi.");
    display.display();
    delay(2000);
  }
  updateDisplay();
}

void setup() {
  // Tugma pinini sozlash
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  // OLED Ekranni ishga tushirish
  if(!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) { 
    for(;;); // Ekran topilmasa tizimni to'xtatish
  }

  // Boshlang'ich ekran yuklanishi
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 20);
  display.println("Yuklanmoqda...");
  display.display();

  // Asosiy ESP funksiyalarini o'chirish (Sizning kodingiz)
  esp_bt_controller_deinit();
  esp_wifi_stop();
  esp_wifi_deinit();
  esp_wifi_disconnect();
  if (esp_bluedroid_get_status() == ESP_BLUEDROID_STATUS_ENABLED) {
    esp_bluedroid_deinit();
    esp_bluedroid_disable();
  }

  // NRF modullarini sozlash (Sizning kodingiz)
  initHSPI();
  initVSPI();

  // RC522 RFID modulini ishga tushirish
  mfrc522.PCD_Init();

  // Ekranni birinchi rejimga yangilash
  updateDisplay();
}

void loop() {
  // Har doim tugmani tekshirib borish
  checkButton();

  // Qaysi rejim faolligiga qarab ish yuritish
  if (currentMode == MODE_JAMMER) {
    // Agar rejim JAMMER bo'lsa, sizning kodingiz maksimal tezlikda ishlaydi
    channelSweeper();
    randomChannel();
  } 
  else if (currentMode == MODE_RFID_READ) {
    handleRFIDRead();
  }
  else if (currentMode == MODE_RFID_WRITE) {
    handleRFIDWrite();
  }
}
